SELECT * FROM () scoped

    campaign_name LIKE CONCAT('%', #{query.campaignName}, '%')
    AND status = #{query.status}
    AND campaign_type = #{query.campaignType}

ORDER BY update_time DESC, campaign_id DESC

mapper.update:
UPDATE crm_campaign SET won_opportunity_count = (
    SELECT COUNT(*) FROM crm_opportunity opportunity
    WHERE opportunity.tenant_id = #{tenantId} AND opportunity.campaign_id = #{id} AND opportunity.deleted = 0 AND opportunity.stage = 'WON'
        AND EXISTS(SELECT 1 FROM crm_lead campaign_lead WHERE campaign_lead.tenant_id = opportunity.tenant_id AND campaign_lead.campaign_id = #{id}
            AND campaign_lead.deleted = 0 AND campaign_lead.converted_customer_id = opportunity.customer_id AND campaign_lead.create_time >= #{start} AND campaign_lead.create_time < #{end})),
    version = version + 1, update_by = #{actor}, update_time = #{now}
WHERE campaign_id = #{id} AND tenant_id = #{tenantId} AND deleted = 0 AND version = #{version}
